constexpr uint32_t EXTRA_CP[4]     = { 0x2013, 0x2014, 0x2026, 0x00B7 };
constexpr const uint8_t *EXTRA_GLYPH[4] = { EXTRA_0, EXTRA_1, EXTRA_2, EXTRA_3 };

// -- glyph lookup -----------------------------------------------------
// Codepoint lookup (UTF-8 already decoded by the caller).  Returns a
// pointer to 16 row bytes, or nullptr for unsupported characters (renders
// as a blank advance).
inline const uint8_t *glyphForCp(uint32_t cp) {
  if (cp < 128) return GLYPHS_ASCII[cp];
  if (cp >= 0x400 && cp < 0x460) return GLYPHS_CYRILLIC[cp - 0x400];
  for (int i = 0; i < 4; ++i)
    if (cp == EXTRA_CP[i]) return EXTRA_GLYPH[i];
  return nullptr;
}

// ASCII fast path (single-byte, matches the other fonts' interface).
inline const uint8_t *glyphFor(char c) {
  return glyphForCp((uint32_t)(unsigned char)c);
}

